using WolfMark.App.Infrastructure;

namespace WolfMark.App.Theming;

/// <summary>
/// App icon variants (Assets/IconProposals, generated by tools/gen-icon-proposals.py). The chosen one is
/// the window/taskbar icon; the .exe file icon is fixed at build time (Assets/WolfMark.ico = default).
/// </summary>
internal static class AppIcons
{
    public const string Default = "2-riso-wm";

    public static (string Id, string NameKey)[] All { get; } =
    [
        ("1-week-band", R.Icon_WeekBand),
        ("2-riso-wm", R.Icon_RisoWm),
        ("3-notebook-calendar", R.Icon_NotebookCalendar),
        ("4-calendar-page", R.Icon_CalendarPage),
        ("5-wolf", R.Icon_Wolf),
        ("6-calendar-pencil", R.Icon_CalendarPencil),
        ("7-wolf-mark", R.Icon_WolfMark),
    ];

    private static string Folder => Path.Combine(AppContext.BaseDirectory, "Assets", "IconProposals");

    public static string IcoPath(string? id)
    {
        var path = Path.Combine(Folder, (id ?? Default) + ".ico");
        return File.Exists(path) ? path : Path.Combine(AppContext.BaseDirectory, "Assets", "WolfMark.ico");
    }

    public static string PngPath(string id) => Path.Combine(Folder, id + ".png");
}
